begin;
set local statement_timeout='15s';
set local standard_conforming_strings=on;
do $public_seed$
declare
 pages jsonb := '{"HOME":{"ar":{"title":"تواصل بسيط حول المشاكل المحلية","body":"أبلغ عن مشكلة يومية داخل تراب جماعة أباينو، وتابع رد المصالح الجماعية بكل وضوح وخصوصية.\r\n\r\n## شكاية خاصة\r\n\r\nلا يراها المواطنون الآخرون\r\n\r\n## نص ففقط\r\n\r\nلا صور ولا وثائق مطلوبة\r\n\r\n## داخل أباينو\r\n\r\nمواقع الجماعة المعتمدة فقط\r\n\r\n## اكتب المشكلة\r\n\r\nاختر الفئة واكتب وصفاً واضحاً ومختصراً.\r\n\r\n## حدد الموقع\r\n\r\nاختر موقعاً معتمداً داخل جماعة أباينو.\r\n\r\n## تابع الرد\r\n\r\nاستعمل حسابك لمتابعة رد الجماعة.\r\n\r\n## تم الاستلام\r\n\r\nتحصل فوراً على رقم مرجعي.\r\n\r\n## قيد الدراسة\r\n\r\nتراجع المصلحة الفئة والموقع والمضمون.\r\n\r\n## قيد المعالجة\r\n\r\nيتم توجيه المشكلة إلى المصلحة المختصة.\r\n\r\n## الرد والإغلاق\r\n\r\nتقرأ الجواب الرسمي ويمكنك الرجوع إلى السجل."},"fr":{"title":"Un contact plus simple pour les problèmes locaux","body":"Signalez un problème du quotidien dans la commune d’Abaynou et suivez la réponse des services, en toute clarté et confidentialité.\r\n\r\n## Réclamation privée\r\n\r\nInvisible aux autres citoyens\r\n\r\n## Du texte uniquement\r\n\r\nNi photos ni documents\r\n\r\n## Dans Abaynou\r\n\r\nUniquement les lieux approuvés\r\n\r\n## Décrivez le problème\r\n\r\nChoisissez la catégorie et rédigez une description précise.\r\n\r\n## Indiquez le lieu\r\n\r\nChoisissez un lieu approuvé dans la commune.\r\n\r\n## Suivez la réponse\r\n\r\nConsultez la réponse de la Commune dans votre compte.\r\n\r\n## Reçue\r\n\r\nVous obtenez un numéro de référence.\r\n\r\n## À l’étude\r\n\r\nLe service examine la catégorie, le lieu et le contenu.\r\n\r\n## En traitement\r\n\r\nLe problème est orienté vers le service compétent.\r\n\r\n## Réponse et clôture\r\n\r\nConsultez la réponse officielle et l’historique."},"en":{"title":"Simple contact about local issues","body":"Report an everyday problem within Abaynou and follow the Commune’s response with clarity and privacy.\r\n\r\n## Private complaint\r\n\r\nHidden from other citizens\r\n\r\n## Text only\r\n\r\nNo photos or documents\r\n\r\n## Within Abaynou\r\n\r\nApproved locations only\r\n\r\n## Describe the problem\r\n\r\nChoose a category and write a clear description.\r\n\r\n## Choose the location\r\n\r\nSelect an approved location in Abaynou.\r\n\r\n## Follow the response\r\n\r\nRead the Commune’s response in your account.\r\n\r\n## Received\r\n\r\nYou receive a reference number.\r\n\r\n## Under review\r\n\r\nStaff review the category, location and description.\r\n\r\n## In processing\r\n\r\nThe issue goes to the responsible service.\r\n\r\n## Response and closure\r\n\r\nRead the official response and history."}},"HOW_IT_WORKS":{"ar":{"title":"كيف تعمل المنصة؟","body":"دليل واضح من إنشاء الحساب إلى متابعة جواب جماعة أباينو.\n\n## أنشئ حسابك الخاص\n\nاستعمل بريدك الإلكتروني واسمك الكامل، ثم أكد بريدك مرة واحدة عند التسجيل. رقم الهاتف اختياري للتواصل.\n\n## صف المشكلة بالنص\n\nاختر الفئة، اكتب موضوعاً مختصراً، ثم وضح ما حدث ومتى بدأ. لا ترفع صوراً أو وثائق.\n\n## حدد موقعاً داخل أباينو\n\nاختر الدوار من القائمة المعتمدة وأضف شارعاً أو علامة قريبة عند الحاجة.\n\n## راجع ثم أرسل\n\nتأكد من صحة الوصف والموقع. بعد الإرسال تحصل على رقم مرجعي ورسالة تأكيد بالبريد الإلكتروني.\n\n## تابع الحالة والجواب\n\nاطلع على الحالة وسجل المعالجة والجواب الرسمي في فضائك الخاص. لا توجد محادثة أو طلبات توضيح بين المواطن والجماعة.\n\n## حضّر هذه المعلومات\n\nوصف واضح لمشكلة واحدة\n\nالدوار داخل أباينو\n\nعلامة قريبة عند الحاجة\n\nمعلومات تواصل صحيحة\n\n## حالات المتابعة\n\nتم الاستلام ← قيد الدراسة ← قيد المعالجة ← إرسال الجواب ← الإغلاق.\n\nيمكن السحب قبل بدء الدراسة فقط؛ وقد تنتهي الشكاية بعدم القبول مع بيان السبب."},"fr":{"title":"Comment ça marche ?","body":"Un parcours clair, du compte à la réponse de la commune d’Abaynou.\n\n## Créez votre compte\n\nUtilisez votre nom et votre courriel, puis vérifiez une fois votre adresse à l’inscription. Le téléphone est facultatif.\n\n## Décrivez le problème\n\nChoisissez la catégorie, un sujet court et une description des faits. Aucun fichier ni photo.\n\n## Précisez un lieu dans Abaynou\n\nChoisissez un douar approuvé et ajoutez une rue ou un repère si nécessaire.\n\n## Vérifiez et envoyez\n\nRelisez la description et le lieu. Vous recevez une référence et un courriel de confirmation.\n\n## Suivez le statut et la réponse\n\nConsultez l’historique et la réponse officielle dans votre espace. Il n’y a ni conversation ni demande de clarification.\n\n## Informations à préparer\n\nUne description d’un seul problème\n\nLe douar dans Abaynou\n\nUn repère si nécessaire\n\nDes coordonnées exactes\n\n## Statuts de suivi\n\nReçue → À l’étude → En traitement → Réponse envoyée → Clôturée.\n\nRetrait possible avant examen uniquement. Une non-acceptation est accompagnée d’un motif."},"en":{"title":"How it works","body":"A clear journey from creating an account to reading the Commune’s response.\n\n## Create your account\n\nUse your name and email, then verify your email once at signup. A contact phone is optional.\n\n## Describe the issue\n\nChoose a category, short subject and factual description. No photos or files.\n\n## Choose a location in Abaynou\n\nChoose an approved douar and add a street or landmark if useful.\n\n## Review and send\n\nCheck the description and location. You receive a reference number and confirmation email.\n\n## Follow status and response\n\nRead the official response and status history in your account. There are no conversations or clarification requests.\n\n## Prepare this information\n\nA clear description of one issue\n\nThe douar within Abaynou\n\nA landmark if useful\n\nAccurate contact details\n\n## Tracking statuses\n\nReceived → Under review → In processing → Response sent → Closed.\n\nWithdrawal is allowed before review only. Not-accepted cases include a reason."}},"SERVICE_SCOPE":{"ar":{"title":"ما الذي يمكن الإبلاغ عنه؟","body":"تحقق من أن المشكلة محلية، داخل تراب الجماعة، ومن اختصاص المصالح الجماعية.\n\n## النظافة وجمع النفايات\n\nمشكلات النظافة أو تراكم النفايات في الفضاء العام.\n\n## الإنارة العمومية\n\nعطب ظاهر في نقطة أو مصباح تابع للإنارة العمومية.\n\n## الطرق والأرصفة المحلية\n\nحفرة أو تلف في طريق أو رصيف محلي داخل الجماعة.\n\n## المرافق الجماعية\n\nمشكلة في فضاء أو تجهيز تديره جماعة أباينو.\n\n## التشوير المحلي\n\nعلامة أو تشوير طرقي محلي متضرر أو غير واضح.\n\n## مشكلة محلية أخرى\n\nموضوع محلي يمكن للمصالح الجماعية دراسته وتوجيهه. هذه أمثلة؛ الفئات النهائية تحتاج اعتماد الجماعة.\n\n## استعمل المنصة عندما\n\nتوجد المشكلة داخل جماعة أباينو.\n\nتتعلق بفضاء عام أو مرفق جماعي محلي.\n\nيمكن وصفها بوضوح بالنص وتحديد موقعها.\n\nلا تمثل خطراً فورياً أو حالة طوارئ.\n\n## استعمل قناة أخرى عندما\n\nيكون الموقع خارج الجماعة.\n\nتتعلق المسألة بمسطرة قضائية أو قانونية.\n\nتحتاج إلى شكاية إدارية وطنية.\n\nتتعلق بخدمة لا تديرها الجماعة."},"fr":{"title":"Que peut-on signaler ?","body":"Vérifiez que le problème est local, dans Abaynou et de compétence communale.\n\n## Propreté et collecte\n\nDéchets ou problème de propreté dans l’espace public.\n\n## Éclairage public\n\nPoint lumineux ou lampe publique en panne.\n\n## Routes et trottoirs\n\nTrou ou dégradation d’une voie locale dans la commune.\n\n## Équipements communaux\n\nProblème dans un espace ou équipement géré par la Commune.\n\n## Signalisation locale\n\nPanneau local endommagé ou peu lisible.\n\n## Autre problème local\n\nUn sujet local à examiner et orienter. Exemples à confirmer par la Commune avant adoption du catalogue.\n\n## Utilisez la plateforme lorsque\n\nLe problème se trouve dans Abaynou.\n\nIl concerne un espace public ou équipement communal.\n\nVous pouvez le décrire et le localiser.\n\nIl ne constitue pas une urgence.\n\n## Utilisez un autre canal lorsque\n\nLe lieu est hors de la commune.\n\nIl s’agit d’une procédure judiciaire ou juridique.\n\nIl s’agit d’une réclamation administrative nationale.\n\nLe service n’est pas géré par la Commune."},"en":{"title":"What can be reported?","body":"Check that the issue is local, within Abaynou and the Commune’s responsibilities.\n\n## Waste and cleanliness\n\nWaste or cleanliness problems in public spaces.\n\n## Public lighting\n\nA broken public lamp or lighting point.\n\n## Roads and pavements\n\nA pothole or damaged local road or pavement.\n\n## Communal facilities\n\nAn issue in a space or facility managed by the Commune.\n\n## Local signs\n\nDamaged or unclear local road signs.\n\n## Other local issue\n\nA local matter for assessment and routing. Examples require Commune approval before becoming the final catalogue.\n\n## Use the platform when\n\nThe issue is within Abaynou.\n\nIt concerns a public space or communal facility.\n\nYou can describe and locate it.\n\nIt is not an emergency.\n\n## Use another channel when\n\nThe location is outside the Commune.\n\nIt concerns a judicial or legal procedure.\n\nIt is a national administrative complaint.\n\nThe service is not managed by the Commune."}},"FAQ":{"ar":{"title":"الأسئلة الشائعة","body":"إجابات عملية عن الحساب، الخصوصية، الإرسال، والمتابعة.\n\n## هل يمكن للآخرين رؤية شكاياتي؟\n\nلا. شكاياتك خاصة، ولا يطلع عليها إلا أنت والمصالح الجماعية المخولة بمعالجتها. لا توجد لائحة عامة للشكايات.\n\n## هل أحتاج إلى حساب؟\n\nنعم. الدخول بالبريد الإلكتروني، ويؤكد البريد مرة واحدة عند التسجيل. رقم الهاتف اختياري. \n\n## هل يمكنني إرفاق صورة أو وثيقة؟\n\nلا. الشكايات نصية فقط. اكتب وصفاً واضحاً وحدد الموقع وعلامة قريبة عند الحاجة.\n\n## ما المواقع المقبولة؟\n\nدوار أباينو، دوار ايكيسل، دوار توتلين، دوار أبوقال، دوار إد العربا، دوار تبولوت فقط. لا تقبل المنصة مواقع خارج الجماعة.\n\n## هل تعوض المنصة Chikaya.ma؟\n\nلا. هذه قناة محلية للمشكلات اليومية داخل أباينو، ولا تعوض البوابة الوطنية أو المساطر القانونية.\n\n## ماذا يحدث بعد الإرسال؟\n\nتحصل على رقم مرجعي ورسالة تأكيد بالبريد. تراجع الجماعة الشكاية وتوجهها إلى المصلحة المختصة، وتتابع الحالة والجواب في حسابك.\n\n## هل يمكنني الرد على الجماعة؟\n\nلا تتضمن النسخة المعتمدة محادثة ثنائية أو طلبات توضيح. يمكنك قراءة الجواب الرسمي وسجل الحالة فقط.\n\n## هل يمكنني التعديل أو السحب؟\n\nفقط عندما تكون الشكاية في حالة «تم الاستلام» (SUBMITTED)، قبل بدء الدراسة. بعد ذلك لا يمكن تعديلها أو سحبها.\n\n## هل تحفظ المنصة مسودة؟\n\nلا توجد مسودات محفوظة. راجع النص والموقع قبل الإرسال؛ لا تعتمد على حفظ البيانات عند مغادرة الصفحة.\n\n## هل يمكن إعادة فتح شكاية مغلقة؟\n\nلا. لا تتضمن النسخة المعتمدة إعادة فتح الشكايات. يبقى السجل متاحاً للقراءة.\n\n## متى أتلقى الجواب؟\n\nتختلف مدة المعالجة حسب طبيعة المشكلة والمصلحة المختصة. لا نقدم أجلاً غير مؤكد.\n\n## هل المنصة مخصصة للطوارئ؟\n\nلا. عند وجود خطر فوري أو حالة صحية أو أمنية عاجلة، تواصل مباشرة مع الجهة المختصة ولا تنتظر جواب المنصة."},"fr":{"title":"Questions fréquentes","body":"Des réponses pratiques sur le compte, la confidentialité, l’envoi et le suivi.\n\n## Les autres voient-ils mes réclamations ?\n\nNon. Seuls vous et les services habilités y accédez. Il n’existe pas de liste publique.\n\n## Un compte est-il nécessaire ?\n\nOui. La connexion utilise le courriel, vérifié une fois à l’inscription. Le téléphone est facultatif. \n\n## Puis-je joindre un fichier ?\n\nNon. Les réclamations sont uniquement textuelles. Décrivez les faits, le lieu et un repère utile.\n\n## Quels lieux sont acceptés ?\n\nدوار أباينو، دوار ايكيسل، دوار توتلين، دوار أبوقال، دوار إد العربا، دوار تبولوت. Aucun lieu hors de la commune.\n\n## Cela remplace-t-il Chikaya.ma ?\n\nNon. Ce service local ne remplace ni le portail national ni les procédures légales.\n\n## Que se passe-t-il après l’envoi ?\n\nVous obtenez une référence et un courriel de confirmation. La Commune examine et oriente la demande. Le statut et la réponse sont dans votre compte.\n\n## Puis-je répondre à la Commune ?\n\nIl n’y a pas de conversation ni de demande de clarification. Vous consultez la réponse officielle et l’historique.\n\n## Puis-je modifier ou retirer ?\n\nUniquement au statut Reçue (SUBMITTED), avant le début de l’examen.\n\n## Les brouillons sont-ils conservés ?\n\nNon. Aucun brouillon durable n’est enregistré. Relisez avant l’envoi et ne comptez pas sur une sauvegarde en quittant la page.\n\n## Puis-je rouvrir une réclamation ?\n\nNon. Une réclamation clôturée ne peut pas être rouverte. Son historique reste consultable.\n\n## Quand aurai-je une réponse ?\n\nLe délai dépend du problème et du service compétent. Aucun délai non confirmé n’est promis.\n\n## Est-ce un service d’urgence ?\n\nNon. En cas de danger immédiat ou d’urgence médicale ou de sécurité, contactez directement l’autorité compétente."},"en":{"title":"Frequently asked questions","body":"Practical answers about accounts, privacy, submission and tracking.\n\n## Can others see my complaints?\n\nNo. Only you and authorized services can access them. There is no public complaint feed.\n\n## Do I need an account?\n\nYes. Sign in with email, verified once at signup. Phone is optional. \n\n## Can I attach a file?\n\nNo. Complaints are text-only. Describe the facts, location and a useful landmark.\n\n## Which locations are accepted?\n\nدوار أباينو، دوار ايكيسل، دوار توتلين، دوار أبوقال، دوار إد العربا، دوار تبولوت. Locations outside the Commune are not accepted.\n\n## Does it replace Chikaya.ma?\n\nNo. This local service replaces neither the national portal nor legal procedures.\n\n## What happens after submission?\n\nYou receive a reference and confirmation email. The Commune reviews and routes the issue. Read its status and response in your account.\n\n## Can I reply to the Commune?\n\nThere is no two-way conversation or clarification-request flow. You can read the official response and status history.\n\n## Can I edit or withdraw?\n\nOnly while the status is Received (SUBMITTED), before review starts.\n\n## Are drafts saved?\n\nNo durable drafts are stored. Review before sending and do not rely on saving when leaving the page.\n\n## Can I reopen a complaint?\n\nNo. Closed complaints cannot be reopened. Their history remains readable.\n\n## When will I receive a response?\n\nTiming depends on the issue and service. No unconfirmed deadline is promised.\n\n## Is this for emergencies?\n\nNo. Contact the responsible authority directly for immediate danger or urgent health or security matters."}},"CONTACT":{"ar":{"title":"اتصل بجماعة أباينو","body":"معلومات التواصل والاستقبال الإداري."},"fr":{"title":"Contacter la commune d’Abaynou","body":"Coordonnées et accueil administratif."},"en":{"title":"Contact the Commune of Abaynou","body":"Contact and administrative reception information."}},"USER_GUIDE":{"ar":{"title":"دليل الاستعمال","body":"مساعدة مبسطة لاستخدام المنصة.\n\n## إنشاء حساب\n\nاستعمل بريدك الإلكتروني واسمك الكامل وكلمة مرور. أكد بريدك مرة واحدة. الهاتف اختياري. \n\n## كتابة الشكاية\n\nاختر الفئة ووصف المشكلة بالنص فقط دون صور أو وثائق. لا توجد مسودات محفوظة.\n\n## اختيار الموقع\n\nدوار أباينو، دوار ايكيسل، دوار توتلين، دوار أبوقال، دوار إد العربا، دوار تبولوت.\n\n## المراجعة والإرسال\n\nراجع الوصف والموقع قبل التأكيد. تحصل على رقم مرجعي ورسالة تأكيد بالبريد عند الإرسال.\n\n## تتبع المعالجة\n\nاقرأ الحالة والجواب الرسمي في حسابك. لا توجد محادثة ثنائية أو إعادة فتح. التعديل والسحب متاحان فقط في حالة SUBMITTED.\n\n## إذا واجهتك مشكلة\n\nراجع الأسئلة الشائعة أو استعمل صفحة الاتصال بالجماعة."},"fr":{"title":"Guide d’utilisation","body":"Une aide simple pour utiliser la plateforme.\n\n## Créer un compte\n\nUtilisez votre nom, courriel et mot de passe. Vérifiez une fois le courriel. Le téléphone est facultatif. \n\n## Décrire la réclamation\n\nChoisissez une catégorie et décrivez les faits par texte, sans fichiers. Aucun brouillon durable.\n\n## Choisir le lieu\n\nدوار أباينو، دوار ايكيسل، دوار توتلين، دوار أبوقال، دوار إد العربا، دوار تبولوت.\n\n## Vérifier et envoyer\n\nRelisez le contenu et le lieu. Une référence et un courriel confirment l’envoi.\n\n## Suivre le traitement\n\nConsultez le statut et la réponse officielle. Pas de conversation ni de réouverture. Modification et retrait uniquement au statut SUBMITTED.\n\n## Obtenir de l’aide\n\nConsultez la FAQ ou la page de contact."},"en":{"title":"User guide","body":"Simple guidance for using the platform.\n\n## Create an account\n\nUse your name, email and password. Verify email once. Phone is optional. \n\n## Describe the issue\n\nChoose a category and write a text description without attachments. No durable drafts.\n\n## Choose a location\n\nدوار أباينو، دوار ايكيسل، دوار توتلين، دوار أبوقال، دوار إد العربا، دوار تبولوت.\n\n## Review and submit\n\nCheck the content and location. A reference and email confirm submission.\n\n## Track progress\n\nRead the status and official response. No conversations or reopening. Editing and withdrawal only in SUBMITTED.\n\n## Find help\n\nRead the FAQ or visit the contact page."}},"PRIVACY":{"ar":{"title":"سياسة الخصوصية","body":"مسودة للمراجعة من طرف الجماعة قبل الإطلاق العمومي.\r\n\r\n## الغرض من البيانات\r\n\r\nتستخدم بيانات الحساب والشكاية لتقديم الخدمة المحلية ومعالجة الشكايات. يجب اعتماد الأغراض والتفاصيل القانونية من طرف الجماعة.\r\n\r\n## خصوصية الشكايات\r\n\r\nلا توجد لائحة عامة للشكايات. يقتصر الوصول على صاحب الحساب والمصالح المخولة.\r\n\r\n## المعلومات المطلوبة\r\n\r\nالبريد الإلكتروني والاسم الكامل للحساب؛ الهاتف اختياري. الشكايات نصية ولا تقبل ملفات.\r\n\r\n## المدة والحقوق والتواصل\r\n\r\nتحدد الجماعة مدة الاحتفاظ والأساس القانوني ومسار ممارسة الحقوق وبيانات المسؤول قبل اعتماد السياسة. راجع صفحة الاتصال."},"fr":{"title":"Politique de confidentialité","body":"Projet à examiner et approuver par la Commune avant ouverture au public.\r\n\r\n## Finalité des données\r\n\r\nLes données du compte et de la réclamation servent au service local. Les finalités et précisions juridiques doivent être approuvées.\r\n\r\n## Confidentialité des réclamations\r\n\r\nAucune liste publique. Accès réservé au titulaire du compte et aux services habilités.\r\n\r\n## Informations demandées\r\n\r\nNom et courriel pour le compte ; téléphone facultatif. Réclamations textuelles sans fichiers.\r\n\r\n## Durées, droits et contact\r\n\r\nLa Commune doit confirmer les durées de conservation, la base légale, les droits et le contact du responsable avant adoption. Consultez la page Contact."},"en":{"title":"Privacy policy","body":"Draft for Commune review and approval before public launch.\r\n\r\n## Purpose of data\r\n\r\nAccount and complaint data support the local service. Purposes and legal details require Commune approval.\r\n\r\n## Complaint privacy\r\n\r\nNo public complaint feed. Access is limited to the account holder and authorized services.\r\n\r\n## Required information\r\n\r\nName and email for accounts; phone is optional. Complaints are text-only without files.\r\n\r\n## Retention, rights and contact\r\n\r\nThe Commune must confirm retention periods, legal basis, rights and responsible contact before adoption. See Contact."}},"ACCESSIBILITY":{"ar":{"title":"إمكانية الولوج","body":"بيان أولي يحتاج مراجعة واعتماد الجماعة، وليس شهادة مطابقة.\n\n## لوحة المفاتيح والتركيز\n\nاستعمل Tab للتنقل وEnter لتفعيل الروابط والأزرار. يوجد رابط لتجاوز القائمة ومؤشر تركيز مرئي.\n\n## العناوين والقراءة\n\nتستخدم الصفحات عناوين مرتبة ومعالم واضحة، وتفتح الأسئلة الشائعة بلوحة المفاتيح.\n\n## التكبير والشاشات الصغيرة\n\nيتكيف المحتوى مع التكبير والشاشات الصغيرة دون تمرير أفقي في العرض المعتمد.\n\n## اللغة والاتجاه\n\nالعربية من اليمين إلى اليسار؛ الفرنسية والإنجليزية من اليسار إلى اليمين.\n\n## الإبلاغ عن عائق\n\nاستعمل صفحة الاتصال لوصف الصفحة والمشكلة التي واجهتها. يتطلب البيان النهائي مراجعة بالتقنيات المساعدة واعتماد مسار التواصل."},"fr":{"title":"Accessibilité","body":"Déclaration provisoire à valider par la Commune ; elle ne constitue pas une certification.\n\n## Clavier et focus\n\nTab parcourt les contrôles, Entrée active les liens et boutons. Un lien d’évitement et un focus visible sont disponibles.\n\n## Titres et lecture\n\nLes pages utilisent des titres structurés et des repères. La FAQ fonctionne au clavier.\n\n## Zoom et petits écrans\n\nLe contenu s’adapte au zoom et aux petits écrans sans défilement horizontal à la largeur prévue.\n\n## Langue et direction\n\nL’arabe est de droite à gauche ; le français et l’anglais de gauche à droite.\n\n## Signaler une difficulté\n\nUtilisez la page Contact et décrivez la page concernée. La déclaration finale exige une revue avec technologies d’assistance et un canal confirmé."},"en":{"title":"Accessibility","body":"Provisional statement for Commune review, not a compliance certification.\n\n## Keyboard and focus\n\nUse Tab to navigate and Enter to activate controls. A skip link and visible focus are available.\n\n## Headings and reading\n\nPages use structured headings and landmarks. FAQ disclosures support keyboard use.\n\n## Zoom and small screens\n\nContent adapts to zoom and small screens without horizontal scrolling at the supported width.\n\n## Language and direction\n\nArabic is right-to-left; French and English are left-to-right.\n\n## Report a barrier\n\nUse Contact and describe the affected page. The final statement needs assistive-technology review and a confirmed contact channel."}},"TERMS":{"ar":{"title":"شروط الاستخدام","body":"مسودة تحتاج اعتماد الجماعة قبل الإطلاق العمومي.\n\n## غرض الخدمة\n\nتتيح المنصة الإبلاغ عن مشكلات محلية داخل أباينو ومتابعة معالجتها.\n\n## مسؤولية الحساب\n\nاستعمل معلومات صحيحة واحفظ كلمة المرور. الهاتف اختياري والبريد الإلكتروني هو وسيلة الدخول.\n\n## الاستعمال المقبول\n\nصف الوقائع بدقة واحترام، ولا تدرج معلومات شخصية غير ضرورية. لا ترفع ملفات.\n\n## النطاق المحلي\n\nتقتصر الخدمة على المواقع المعتمدة داخل أباينو ولا تعوض Chikaya.ma أو المساطر القانونية.\n\n## حدود الخدمة\n\nالمنصة ليست للطوارئ ولا تتعهد بأجل معالجة غير معتمد. لا توجد محادثة ثنائية أو إعادة فتح.\n\n## تغييرات الشروط\n\nتحدد الجماعة إجراءات وتاريخ سريان التعديلات قبل اعتماد هذه الشروط."},"fr":{"title":"Conditions d’utilisation","body":"Projet soumis à l’approbation de la Commune avant ouverture au public.\n\n## Objet du service\n\nSignaler et suivre des problèmes locaux dans Abaynou.\n\n## Responsabilité du compte\n\nUtilisez des informations exactes et protégez le mot de passe. Connexion par courriel ; téléphone facultatif.\n\n## Usage acceptable\n\nDécrivez les faits avec précision et respect, sans données personnelles inutiles ni fichiers.\n\n## Périmètre local\n\nLieux approuvés dans Abaynou uniquement. Ce service ne remplace ni Chikaya.ma ni les procédures légales.\n\n## Limites du service\n\nNi urgences ni délai non confirmé. Aucune conversation ou réouverture.\n\n## Évolution des conditions\n\nLa Commune doit confirmer la procédure de modification et la date d’entrée en vigueur."},"en":{"title":"Terms of use","body":"Draft requiring Commune approval before public launch.\n\n## Service purpose\n\nReport and track local issues within Abaynou.\n\n## Account responsibility\n\nUse accurate information and protect your password. Email is the login identifier; phone is optional.\n\n## Acceptable use\n\nDescribe facts accurately and respectfully, without unnecessary personal data or files.\n\n## Local scope\n\nApproved locations within Abaynou only. This service does not replace Chikaya.ma or legal procedures.\n\n## Service limitations\n\nNot for emergencies. No unconfirmed response deadline, conversations or reopening.\n\n## Changes to terms\n\nThe Commune must confirm the amendment process and effective date before adoption."}}}'::jsonb;
 settings_bundle jsonb := '{"ar":{"commune_name":"أباينو تتواصل — نسخة تجريبية","public_address":"عنوان تجريبي غير رسمي — في انتظار الاعتماد","opening_hours":"أوقات تجريبية غير رسمية — في انتظار الاعتماد"},"fr":{"commune_name":"Abaynou Tatawasal — démonstration","public_address":"Adresse de démonstration non officielle — à approuver","opening_hours":"Horaires de démonstration non officiels — à approuver"},"en":{"commune_name":"Abaynou Tatawasal — development preview","public_address":"Non-official demonstration address — approval pending","opening_hours":"Non-official demonstration hours — approval pending"}}'::jsonb;
 expected_keys text[]:=array['ACCESSIBILITY','CONTACT','FAQ','HOME','HOW_IT_WORKS','PRIVACY','SERVICE_SCOPE','TERMS','USER_GUIDE'];actual_keys text[];
 item record;page record;settings_count bigint;existing_settings_id uuid;languages text[];
begin
 if current_user<>'postgres' then raise exception 'STAGING_INITIALIZER_REQUIRES_OWNER';end if;
 if not exists(select 1 from pg_catalog.pg_roles where rolname=current_user and (rolsuper or rolbypassrls)) then raise exception 'STAGING_INITIALIZER_REQUIRES_OWNER_RLS_BYPASS';end if;
 if not exists(select 1 from supabase_migrations.schema_migrations where version='20261015000200') then raise exception 'COMPLETE_REVIEWED_MIGRATIONS_FIRST';end if;
 perform pg_advisory_xact_lock(71919009);
 perform 1 from app.public_pages order by page_key for update;
 select array_agg(page_key order by page_key) into actual_keys from app.public_pages;
 if actual_keys is distinct from expected_keys then raise exception 'FIXED_PUBLIC_PAGE_IDENTITY_CONFLICT';end if;
 for item in select key,value from jsonb_each(pages) loop
  select id,current_version,revision into page from app.public_pages where page_key=item.key;
  if page.current_version is null then perform app.publish_development_page(item.key,page.revision,item.value);end if;
 end loop;
 perform 1 from app.commune_settings for update;
 select count(*) into settings_count from app.commune_settings;
 if settings_count>1 then raise exception 'COMMUNE_SETTINGS_SINGLETON_CONFLICT';end if;
 if settings_count=0 then
  perform app.configure_development_settings(0,'+00000000000','commune@example.invalid','https://chikaya.ma/',settings_bundle);
 else
  select id into existing_settings_id from app.commune_settings;
  select array_agg(language order by language) into languages from app.commune_settings_translations t where t.settings_id=existing_settings_id;
  if languages is distinct from array['ar','en','fr']::text[] then raise exception 'COMMUNE_SETTINGS_TRANSLATION_CONFLICT';end if;
 end if;
end $public_seed$;
commit;

select (select count(*) from app.public_pages where current_version is not null) as published_pages,
 (select count(*) from app.public_pages p join app.public_page_versions v on v.page_id=p.id and v.version_number=p.current_version join app.public_page_translations t on t.version_id=v.id) as current_page_translations,
 (select count(*) from app.commune_settings_translations) as settings_languages;
